SELECT quote_id quoteId,store_id storeId,terminal_id terminalId,business_time businessTime,currency,
       request_sha256 requestSha256,result_sha256 resultSha256,engine_version engineVersion,
       package_version packageVersion,gross_amount_minor grossAmountMinor,
       discount_amount_minor discountAmountMinor,payable_amount_minor payableAmountMinor
FROM prm_quote WHERE tenant_id=#{tenantId} AND store_id=#{storeId}
  AND terminal_id=#{terminalId} AND idempotency_key=#{key}
